from fractions import Fraction
def scatter_plot(points, xmin, xmax, ymin, ymax):
    for y in range(ymax, ymin - 1, -1):
        row = ""
        for x in range(xmin, xmax + 1):
            if (x, y) in points:
                mark = "*"
            elif x == xmin and y == ymin:
                mark = "+"
            elif x == xmin:
                mark = "|"
            elif y == ymin:
                mark = "-"
            else:
                mark = "."
            row = row + mark + " "
        print(row)

def describe(label, points, xmin, xmax, ymin, ymax):
    print(label)
    scatter_plot(points, xmin, xmax, ymin, ymax)
    n = len(points)
    xbar = Fraction(sum(p[0] for p in points), n)
    ybar = Fraction(sum(p[1] for p in points), n)
    agree = len([p for p in points if (p[0] - xbar) * (p[1] - ybar) > 0])
    disagree = len([p for p in points if (p[0] - xbar) * (p[1] - ybar) < 0])
    print(f"mean point ({float(xbar):.2f}, {float(ybar):.2f}): {agree} agree, {disagree} disagree, {n - agree - disagree} on a mean line")
    if agree > disagree:
        print("direction: positive")
    elif agree < disagree:
        print("direction: negative")
    else:
        print("direction: none clear")
